$adminTitle='Orders';require __DIR__.'/_header.php';require_once __DIR__.'/../includes/commerce.php';$pdo=db();$ready=commerce_schema_ready($pdo);$error='';$view=(int)($_GET['view']??$_POST['order_id']??0);
if($pdo&&$ready&&$_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_valid($_POST['csrf_token']??null))$error='Your session expired.';else{try{$action=(string)($_POST['action']??'');if($action==='fulfil'){commerce_fulfil_order($pdo,$view,trim((string)($_POST['courier']??'')),trim((string)($_POST['service']??''))?:null,trim((string)($_POST['tracking']??''))?:null,trim((string)($_POST['notes']??''))?:null,(int)(admin_user()['id']??0)?:null);header('Location: orders.php?view='.$view.'&fulfilled=1');exit;}if($action==='note'){$pdo->prepare('UPDATE sales_orders SET admin_note=:note WHERE id=:id')->execute(['note'=>trim((string)($_POST['admin_note']??''))?:null,'id'=>$view]);header('Location: orders.php?view='.$view.'&saved=1');exit;}if($action==='cancel'){$s=$pdo->prepare('SELECT payment_status,fulfilment_status FROM sales_orders WHERE id=:id');$s->execute(['id'=>$view]);$state=$s->fetch();if(!$state||$state['payment_status']!=='Pending'||$state['fulfilment_status']==='Fulfilled')throw new RuntimeException('Only unpaid, unfulfilled orders can be cancelled here. Paid orders require a separate refund/reconciliation process.');$pdo->beginTransaction();$pdo->prepare("UPDATE sales_orders SET status='Cancelled',payment_status='Cancelled',cancelled_at=NOW() WHERE id=:id")->execute(['id'=>$view]);$pdo->prepare("UPDATE stock_reservations SET status='Released' WHERE order_id=:id AND status='Active'")->execute(['id'=>$view]);$pdo->commit();header('Location: orders.php?view='.$view.'&cancelled=1');exit;}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Order operation failed.';}}
}
$orders=$ready?$pdo->query('SELECT * FROM sales_orders ORDER BY created_at DESC LIMIT 300')->fetchAll():[];$order=null;$items=[];$reservations=[];$payments=[];$shipments=[];if($ready&&$view){$s=$pdo->prepare('SELECT * FROM sales_orders WHERE id=:id');$s->execute(['id'=>$view]);$order=$s->fetch()?:null;if($order){$s=$pdo->prepare('SELECT * FROM sales_order_items WHERE order_id=:id');$s->execute(['id'=>$view]);$items=$s->fetchAll();$s=$pdo->prepare('SELECT r.*,b.batch_number,p.sku FROM stock_reservations r JOIN inventory_batches b ON b.id=r.batch_id JOIN products p ON p.id=b.product_id WHERE r.order_id=:id ORDER BY r.id');$s->execute(['id'=>$view]);$reservations=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM payment_transactions WHERE order_id=:id ORDER BY received_at DESC');$s->execute(['id'=>$view]);$payments=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM order_shipments WHERE order_id=:id ORDER BY created_at DESC');$s->execute(['id'=>$view]);$shipments=$s->fetchAll();}}
