<div class="admin-heading"><div><div class="eyebrow">Sales</div><h1>Orders</h1></div><a class="btn" href="commerce.php">Commerce</a></div><?php if(!$ready):?><div class="alert error">V6 commerce is not installed.</div><?php endif;?><?php if(isset($_GET['fulfilled'])):?><div class="alert success">Order fulfilled and reserved stock consumed.</div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert success">Order note saved.</div><?php endif;?><?php if(isset($_GET['cancelled'])):?><div class="alert success">Order cancelled.</div><?php endif;?><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?>
