alid']?'Sig✓':'Sig✗' ?> · <?= $p['source_valid']?'Src✓':'Src✗' ?> · <?= $p['amount_valid']?'Amt✓':'Amt✗' ?> · <?= $p['server_valid']?'Srv✓':'Srv✗' ?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="5">No gateway notifications recorded.</td></tr><?php endif;?></tbody></table></div><h3>Shipments</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Dispatched</th><th>Courier</th><th>Tracking</th></tr></thead><tbody><?php foreach($shipments as $sh):?><tr><td><?= e($sh['dispatched_at']) ?></td><td><?= e(trim(($sh['courier']??'').' '.($sh['service']??''))) ?></td><td><?= e($sh['tracking_number']) ?></td></tr><?php endforeach;?><?php if(!$shipments):?><tr><td colspan="3">No shipments recorded.</td></tr><?php endif;?></tbody></table></div><?php if($order['payment_status']==='Pending'&&$order['fulfilment_status']!=='Fulfilled'):?><form method="post" class="admin-section-gap"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><button class="btn" type="submit">Cancel unpaid order</button></form><?php endif;?><?php if($order['payment_status']==='Paid'&&$order['fulfilment_status']!=='Fulfilled'):?><form method="post" class="card admin-section-gap"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="fulfil"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><h3>Dispatch order</h3><div class="form-grid"><div class="field"><label>Courier</label><input name="courier" maxlength="100" required></div><div class="field"><label>Service</label><input name="service" maxlength="100"></div><div class="field full"><label>Tracking number</label><input name="tracking" maxlength="160"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div><button class="btn primary">Dispatch & consume reserved stock</button></form><?php endif;?><form method="post" class="admin-section-gap"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="note"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><div class="field"><label>Admin note</label><textarea name="admin_note"><?= e($order['admin_note']) ?></textarea></div><button class="btn">Save note</button></form></section><?php endif;?>
